import org.eclipse.rdf4j.query.algebra.Union;
import org.eclipse.rdf4j.query.algebra.evaluation.QueryBindingSet;
import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.OptimizationGoal;
import org.junit.jupiter.api.Test;

class PackedWholeRowObservationTest {
	private static final PackedCostModel COSTS = (query, id) -> 1.0d;
	private static final PackedPlanCache.Context CACHE_CONTEXT = new PackedPlanCache.Context(1, 2, 3, 4, 5, 6, 7);

	@Test
	void optionalBindingObservedOnlyByWholeRowDistinctSurvivesPackedPlanningAndCache() {
		for (ConditionBindingScope scope : List.of(ConditionBindingScope.AUTO, ConditionBindingScope.ALL,
				ConditionBindingScope.retain(Set.of("x")), ConditionBindingScope.retain(Set.of()))) {
			TupleExpr source = query(scope);
			List<String> expected = scope.equals(ConditionBindingScope.retain(Set.of())) ? List.of() : List.of("");
			assertThat(PackedPlanDifferentialSupport.evaluate(PackedPlanDifferentialSupport.model(), source))
					.as("ordinary algebra establishes whether the whole input mapping reaches EXISTS")
					.isEqualTo(expected);
			PackedQuery raw = PackedQueryCodec.encode(source.clone());
			assertThat(PackedPlanDifferentialSupport.evaluate(PackedPlanDifferentialSupport.model(),
					PackedPlanMaterializer.materialize(raw, raw.rootRelId()))).isEqualTo(expected);
			PackedQuery planned = PackedQueryCodec.encodeForPlanning(source.clone());
			int rootGroup = planned.relGroup(planned.rootRelId());
			for (int relation = 1; relation <= planned.relationCount(); relation++) {
				if (planned.relGroup(relation) == rootGroup
						&& (planned.relRuleMask(relation) & PackedRuleProofs.REMOVE_UNUSED_OPTIONAL) != 0L) {
					TupleExpr alternative = PackedPlanMaterializer.materialize(planned, relation);
					assertThat(
							PackedPlanDifferentialSupport.evaluate(PackedPlanDifferentialSupport.model(), alternative))
									.as("every naturally generated optional-pruning alternative must retain the baseline bag")
									.isEqualTo(expected);
				}
			}
			PackedPlanCache cache = new PackedPlanCache(8, 1);
			PackedPlanningResult cold = PackedCascadesPlanner.optimize(source.clone(), OptimizationGoal.root(), cache,
					CACHE_CONTEXT, COSTS);
			PackedPlanningResult warm = PackedCascadesPlanner.optimize(source.clone(), OptimizationGoal.root(), cache,
					CACHE_CONTEXT, COSTS);
			assertThat(cold.metrics().groups()).isPositive();
			assertThat(cold.metrics().winners()).isPositive();
			assertThat(cold.metrics().planCacheHit()).isFalse();
			assertThat(warm.metrics().planCacheHit()).isTrue();
			assertThat(
					PackedPlanDifferentialSupport.evaluate(PackedPlanDifferentialSupport.model(), cold.selectedPlan()))
							.isEqualTo(expected);
			assertThat(
					PackedPlanDifferentialSupport.evaluate(PackedPlanDifferentialSupport.model(), warm.selectedPlan()))
							.isEqualTo(expected);
		}
	}

	private static TupleExpr query(ConditionBindingScope scope) {
		QueryBindingSet binding = new QueryBindingSet();
		binding.addBinding("x", SimpleValueFactory.getInstance().createLiteral(1));
		BindingSetAssignment right = new BindingSetAssignment();
		right.setDeclaredBindingNames(Set.of("x"));
		right.setBindingSets(List.of(binding));
		LeftJoin optional = new LeftJoin(new SingletonSet(), right);
		TupleExpr emptyProjection = new Projection(new SingletonSet(), new ProjectionElemList(), false);
		TupleExpr body = new Slice(new Distinct(new Union(new SingletonSet(), emptyProjection)), 1, 1);
		Filter filter = new Filter(optional, new Exists(body));
		filter.setConditionBindingScope(scope);
		return new Distinct(new Projection(filter, new ProjectionElemList(), false));
	}
}
